 /// </summary>
 [McpServerToolType]
 public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
 {
     private static readonly JsonSerializerOptions JsonOptions = new() { WriteIndented = true };

     [McpServerTool, Description("List all items from the API.")]
     public async Task<string> ListItems(CancellationToken cancellationToken = default)
     {
         logger.LogInformation("Listing all items");
         var json = await httpClient.GetStringAsync("/items", cancellationToken);
         return json;
     }

     [McpServerTool, Description("Get a single item by its ID.")]
     public async Task<string> GetItem(
         [Description("The unique identifier of the item to retrieve")] int id,
         CancellationToken cancellationToken = default)
     {
         logger.LogInformation("Getting item {Id}", id);
         var response = await httpClient.GetAsync($"/items/{id}", cancellationToken);

         if (!response.IsSuccessStatusCode)
         {
             return $"Error: API returned {(int)response.StatusCode} {response.ReasonPhrase}";
         }

         var json = await response.Content.ReadAsStringAsync(cancellationToken);
         return json;
     }

     [McpServerTool, Description("Create a new item with a title and optional body.")]
     public async Task<string> CreateItem(
         [Description("Title of the new item")] string title,
         [Description("Optional body/content of the item")] string? body = null,
         CancellationToken cancellationToken = default)
     {
         logger.LogInformation("Creating item with title '{Title}'", title);

         var payload = JsonSerializer.Serialize(new { title, body }, JsonOptions);
         var content = new StringContent(payload, Encoding.UTF8, "application/json");
         var response = await httpClient.PostAsync("/items", content, cancellationToken);

         var result = await response.Content.ReadAsStringAsync(cancellationToken);
         return response.IsSuccessStatusCode
             ? result
             : $"Error: API returned {(int)response.StatusCode} — {result}";
     }

     [McpServerTool(ReadOnly = true), Description("Search items by keyword in the title.")]
     public async Task<string> SearchItems(
         [Description("Keyword to search for in item titles")] string query,
         CancellationToken cancellationToken = default)
     {
         logger.LogInformation("Searching items with query '{Query}'", query);
         var encoded = Uri.EscapeDataString(query);
         var json = await httpClient.GetStringAsync($"/items?q={encoded}", cancellationToken);
         return json;
     }
 }

